import * as F from './engine.js';
import {open,save} from './store.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=F.money,d=F.today();let state,page='inicio',chat=[],busy=false;
const pages=[['inicio','◫','Visão geral'],['movimentacoes','⇄','Movimentações'],['cartoes','▤','Cartão compartilhado'],['planejamento','◷','Planejamento'],['desejos','♡','Meus desejos'],['patrimonio','▥','Patrimônio'],['relatorios','≡','Relatórios'],['consultor','✧','Meu consultor'],['configuracoes','⚙','Configurações']];
const typeNames={income:'Receita recorrente',extra:'Receita extraordinária',expense:'Despesa pessoal',sent:'Dinheiro enviado a terceiros',transfer:'Transferência interna',reimbursement:'Reembolso recebido',invoice:'Pagamento de fatura',refund:'Estorno'};
const categories=['Alimentação','Moradia','Faculdade','Transporte','Saúde','Lazer','Compras','Assinaturas','Outros'];
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const opts=(a,selected)=>a.map(x=>option(x,x,selected)).join('');
const field=(name,label,type='text',value='',extra='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const select=(name,label,options)=>`<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options}</select>`;
const val=n=>(n/100).toFixed(2).replace('.',',');
const btn=(text,act,id='',cls='')=>`<button class="${cls}" data-action="${act}" data-id="${esc(id)}">${text}</button>`;
const empty=(text,action='',label='Cadastrar')=>`<div class="empty"><span class="empty-symbol">◌</span>${text}${action?`<p>${btn(label,action,'','primary')}</p>`:''}</div>`;
const heading=(title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">SEU ESPAÇO FINANCEIRO</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const stat=(label,value,note,symbol='↗')=>`<div class="card stat"><div class="label">${label}<span class="symbol">${symbol}</span></div><strong>${fmt(value)}</strong><small>${note}</small></div>`;
const accountOptions=(selected,all=false)=>state.accounts.filter(a=>all||a.kind==='cash').map(a=>option(a.id,a.name,selected)).join('');
const formError='<p class="error" role="alert" id="form-error"></p>';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();}
async function commit(action,fn){if(busy)return false;busy=true;try{const next=structuredClone(state);fn(next);F.validate(next);state=await save(next,action);close();render();toast('Salvo neste dispositivo.');return true;}catch(e){const target=$('#form-error');if(target)target.textContent=e.message;else toast(e.message);return false;}finally{busy=false;}}
function bindForm(handler){$('#modal form').onsubmit=async e=>{e.preventDefault();if(busy)return;try{await handler(Object.fromEntries(new FormData(e.target)));}catch(err){$('#form-error').textContent=err.message;}};}
function welcome(){return !state.accounts.length?`<div class="welcome"><h3>Comece com a sua realidade.</h3><p>Seu espaço está vazio. Primeiro, cadastre o saldo atual de uma conta. Depois configure o salário e registre seus compromissos. Nenhum número de demonstração será usado.</p>${btn('＋ Cadastrar minha primeira conta','account','','primary')}</div>`:'';}
function dashboard(){const s=F.snapshot(state),receivable=Object.values(s.receivables).reduce((a,r)=>a+r.pending,0);return heading('Olá, Gabriel. Vamos organizar?','Um pouco de clareza para aproveitar melhor o seu dinheiro.',`<span class="pill">${new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'America/Sao_Paulo'}).format(new Date())}</span>`)+welcome()+
`${s.unknown||s.unclassified?`<div class="notice">${s.unclassified?`${s.unclassified} compra(s) aguardam identificação do responsável. `:''}${s.unknown?`${s.unknown} compromisso(s) estão sem valor definido. `:''}Seu planejamento ainda precisa dessas informações.</div>`:''}${s.shortfall?`<div class="notice">A projeção indica insuficiência de ${fmt(s.shortfall)}. Reveja os compromissos e as datas antes de assumir novas despesas.</div>`:''}
<div class="grid two"><section class="card hero"><div class="row between"><span class="eyebrow">LIVRE PARA APROVEITAR</span><span class="pill">Com planejamento</span></div><div class="big">${fmt(s.free)}</div><p>É quanto você pode usar considerando suas contas, reservas e o fluxo de caixa dos próximos 90 dias.</p>${btn('Entender meu disponível ↗','explain')}</section><section class="card advice"><div><div class="icon">✧</div><h2>Seu próximo passo, com clareza.</h2><p>${state.accounts.length?'Antes de comprar, veja como a decisão afeta suas prioridades. Seu consultor usa os registros que você cadastrou.':'Dê um destino ao seu salário e transforme planos em decisões possíveis.'}</p></div><div>${btn('Conversar com meu consultor →','goto','consultor')}</div></section></div>
<div class="grid four stats">${stat('Saldo nas contas',s.cash,'Somente contas de uso diário','▣')}${stat('Consumo pessoal no mês',s.personal,'Sem terceiros e sem duplicidades','↗')}${stat('Faturas a pagar',s.debt,'Obrigação integral com o banco','▤')}${stat('A receber de terceiros',receivable,'Não entra no dinheiro livre','⇄')}</div>
<div class="grid two"><section class="card"><div class="top"><h2>Seu saldo nos próximos meses</h2><span class="pill">Projeção de caixa</span></div>${projection(s)}<p class="help">Confirmado: lançamentos e obrigações com valor definido. Com estimativas: inclui salário previsto e aportes futuros. Não pressupõe rendimentos.</p></section><section class="card"><div class="top"><h2>Próximos compromissos</h2>${btn('Ver todos →','goto','planejamento','link')}</div>${upcoming(s)}</section></div>
<div class="grid two"><section class="card"><div class="top"><h2>Planos que ganham forma</h2>${btn('Planejar →','goto','planejamento','link')}</div>${state.goals.slice(0,3).map(goalMini).join('')||empty('Seu próximo objetivo pode começar pequeno.','goal','Criar um plano')}</section><section class="card"><div class="top"><h2>Desejar também faz parte</h2>${btn('Meus desejos →','goto','desejos','link')}</div>${state.wishes.filter(w=>w.status!=='comprado').slice(0,3).map(w=>`<div class="item"><div class="row"><div class="item-icon">♡</div><div><div class="name">${esc(w.name)}</div><p>${esc(F.assess(state,w.amount,d,w).status)}</p></div></div><span class="amount">${fmt(w.amount)}</span></div>`).join('')||empty('Reserve espaço para o que você gosta.','wish','Adicionar desejo')}</section></div>
${budgetCard()}<div class="grid four stats">${stat('Salário mensal líquido',state.settings.salary,'Previsão • próximo: '+s.nextSalary)}${stat('Envelopes protegidos',s.envelope,'Planos e desejos, sem sobreposição')}${stat('Reserva e investimentos',s.protectedAccounts,'Contas fora do orçamento de consumo')}${stat('Fatura realmente sua',s.invoices.reduce((a,i)=>a+i.personal,0),'Todas as faturas cadastradas')}</div>`;}
function projection(s){const max=Math.max(1,...s.projections.flatMap(p=>[Math.abs(p.confirmed),Math.abs(p.estimated)]));return `<div class="chart" role="img" aria-label="Projeções em 30, 60 e 90 dias">${s.projections.map(p=>`<div class="chart-col"><span>${fmt(p.estimated)}</span><div class="bars"><div class="bar confirmed" style="height:${Math.max(2,Math.abs(p.confirmed)/max*105)}px"></div><div class="bar" style="height:${Math.max(2,Math.abs(p.estimated)/max*105)}px"></div></div><span>${p.days} dias</span></div>`).join('')}</div><div class="legend"><span><i></i>Confirmado</span><span><i class="light"></i>Com estimativas</span></div><details><summary>Ver valores exatos</summary>${s.projections.map(p=>`<p>${p.days} dias: confirmado ${fmt(p.confirmed)} · com estimativas ${fmt(p.estimated)}</p>`).join('')}</details>`;}
function upcoming(s){const rows=s.events.filter(e=>e.amount<0&&!e.name.startsWith('Planejamento:')).slice(0,4);return rows.map(e=>`<div class="item"><div class="row"><span class="item-icon">◷</span><div><div class="name">${esc(e.name)}</div><p>${e.date} · ${e.confirmed?'Confirmado':'Estimativa'}</p></div></div><span class="amount">${fmt(-e.amount)}</span></div>`).join('')||empty('Você ainda não tem contas previstas.','bill','Cadastrar compromisso');}
function goalMini(g){return `<div class="item" style="display:block"><div class="row between"><span class="name">${esc(g.name)}</span><span class="compact">${g.target===null?'Valor a definir':fmt(g.reserved)+' / '+fmt(g.target)}</span></div><div class="progress"><span style="width:${g.target?Math.min(100,g.reserved/g.target*100):0}%"></span></div><div class="row between"><small>${g.due}</small><small>${g.target===null?'Estimativa pendente':fmt(F.monthlySaving(g))+' por período'}</small></div></div>`;}
function movements(){return heading('Cada movimento tem um destino.','Consumo, transferências e obrigações separados para você entender seu dinheiro.',btn('＋ Registrar','entry','','primary'))+welcome()+`<div class="filters"><input id="search" aria-label="Buscar movimentação" placeholder="Buscar descrição…"><input type="month" id="filter-month" aria-label="Mês" value="${d.slice(0,7)}"><select id="filter-account" aria-label="Conta"><option value="">Todas as contas</option>${accountOptions('',true)}</select><select id="filter-category" aria-label="Categoria"><option value="">Todas as categorias</option>${opts(categories)}</select></div><section class="card"><div id="movement-table"></div></section>`;}
function movementRows(){if(!$('#movement-table'))return;const q=$('#search').value.toLowerCase(),month=$('#filter-month').value,acc=$('#filter-account').value,cat=$('#filter-category').value;const rows=state.entries.filter(e=>(!q||e.name.toLowerCase().includes(q))&&(!month||e.date.startsWith(month))&&(!acc||e.account===acc||e.to===acc)&&(!cat||e.category===cat)).sort((a,b)=>b.date.localeCompare(a.date));$('#movement-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Tipo / conta</th><th>Valor</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${e.date}</td><td>${esc(e.name)}<small>${esc(e.category||'')}</small></td><td>${typeNames[e.type]}<small>${esc(state.accounts.find(a=>a.id===e.account)?.name)}${e.to?' → '+esc(state.accounts.find(a=>a.id===e.to)?.name):''}</small></td><td>${fmt(e.amount)}</td><td>${btn('Reverter','delete-entry',e.id,'danger')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma movimentação para estes filtros.');}
function cards(){let s=F.snapshot(state),inv=s.invoices;return heading('Um cartão. Cada pessoa, sua parte.','A fatura é sua obrigação com o banco. O consumo de terceiros é um valor a receber.',`<div class="actions">${btn('Importar fatura','import')}${btn('＋ Compra','purchase','','primary')}</div>`)+
`<div class="grid three stats">${stat('Total a pagar ao banco',s.debt,'Faturas em aberto')}${stat('Seu consumo no cartão',inv.reduce((a,i)=>a+i.personal,0),'Após estornos, todas as faturas')}${stat('Reembolsos pendentes',Object.values(s.receivables).reduce((a,r)=>a+r.pending,0),'Por compra e responsável')}</div><section class="card"><div class="top"><h2>Faturas</h2><span class="pill">Pagamento não duplica consumo</span></div>${inv.length?inv.map(i=>`<div class="item"><div><div class="name">${esc(i.card)} · ${i.due}</div><p>Total ${fmt(i.total)} · Gabriel ${fmt(i.personal)} · Pago ${fmt(i.paid)}${i.unknown?' · A identificar '+fmt(i.unknown):''}</p></div><div class="actions">${i.pending?btn('Pagar '+fmt(i.pending),'pay-invoice',i.key):`<span class="pill">Quitada${i.paid>i.total?' · crédito '+fmt(i.paid-i.total):''}</span>`}</div></div>`).join(''):empty('Nenhuma compra cadastrada.','import','Importar minha fatura')}</section>
<section class="card"><div class="top"><h2>Quem precisa reembolsar</h2>${btn('Relatório mensal →','goto','relatorios','link')}</div>${Object.entries(s.receivables).map(([p,r])=>`<div class="item"><div><div class="name">${esc(p)}</div><p>Parte total ${fmt(r.total)} · Recebido ${fmt(r.paid)}</p></div><div><div class="amount">${fmt(r.pending)}</div><div class="actions" style="margin-top:8px">${p!=='Não identificado'?btn('Copiar cobrança','collect',p):''}</div></div></div>`).join('')||empty('As partes de terceiros aparecerão aqui.')}</section>
<div class="filters"><input id="card-search" aria-label="Buscar compra" placeholder="Buscar compra…"><input type="month" id="card-month" aria-label="Mês da fatura" value="${d.slice(0,7)}"><select id="card-person" aria-label="Responsável"><option value="">Todas as pessoas</option>${opts([...new Set(['Gabriel','Mãe','Não identificado',...state.purchases.flatMap(p=>p.splits.map(x=>x.person))])])}</select><select id="card-category" aria-label="Categoria"><option value="">Todas as categorias</option>${opts(categories)}</select></div><section class="card"><div id="purchase-table"></div></section>`;}
function purchaseRows(){if(!$('#purchase-table'))return;const q=$('#card-search').value.toLowerCase(),month=$('#card-month').value,person=$('#card-person').value,cat=$('#card-category').value;const rows=state.purchases.filter(p=>(!q||p.description.toLowerCase().includes(q))&&(!month||p.due.startsWith(month))&&(!person||p.splits.some(x=>x.person===person))&&(!cat||p.category===cat)).sort((a,b)=>b.date.localeCompare(a.date));$('#purchase-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Compra / data</th><th>Responsáveis</th><th>Valor / parcela</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.description)}<small>${p.date} · ${esc(p.category)} · ${esc(p.card)}</small></td><td>${F.splitRefund(state,p).map(x=>`${esc(x.person)}: ${fmt(x.amount)}`).join('<br>')}</td><td>${fmt(p.amount)}<small>${p.installment||1}/${p.installments||1} · vence ${p.due}</small></td><td><div class="actions">${btn('Dividir / corrigir','split',p.id)}${btn('Reembolso','reimburse',p.id)}${btn('Estorno','refund',p.id)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma compra para estes filtros.');}
function planning(){return heading('O futuro fica mais leve com um plano.','Contas recorrentes e envelopes para os compromissos que vêm pela frente.',`<div class="actions">${btn('＋ Conta fixa','bill')}${btn('＋ Plano futuro','goal','','primary')}</div>`)+`<section class="card"><div class="top"><h2>Compromissos e contas fixas</h2><span class="pill">Próximos 90 dias + atrasados</span></div>${F.occurrences(state,'2000-01-01',F.addDays(d,90)).map(b=>`<div class="item"><div><div class="name">${esc(b.name)} <span class="pill ${b.occurrence<d?'bad':b.estimated?'warn':''}">${b.occurrence<d?'Atrasado':b.amount===null?'A definir':b.estimated?'Estimativa':'Previsto'}</span></div><p>${b.occurrence} · ${esc(b.category)} · prioridade ${b.priority} · ${b.recurring?'Mensal':'Única'}</p></div><div><div class="amount">${b.amount===null?'Sem valor':fmt(b.amount)}</div><div class="actions" style="margin-top:8px">${btn('Editar','bill',b.id)}${b.amount!==null?btn('Pagar','pay-bill',b.id+'|'+b.occurrence):''}${btn('Encerrar','delete-bill',b.id)}</div></div></div>`).join('')||empty('Nenhum compromisso pendente.','bill','Cadastrar conta')}</section><div class="row between"><h2>Envelopes para despesas futuras</h2><small>Reservas virtuais dentro do saldo das contas</small></div><div class="grid three section-space">${state.goals.map(g=>`<section class="card">${goalMini(g)}<p class="help">${g.target===null?'Defina uma estimativa quando souber o custo.':`Faltam ${fmt(g.target-g.reserved)}. Separar ${fmt(F.monthlySaving(g))} em cada um dos ${g.periods} período(s) restantes.`}</p><div class="actions">${btn('Reservar','reserve-goal',g.id)}${btn('Editar','goal',g.id)}${btn('Usar / pagar','spend-goal',g.id)}${btn('Encerrar','delete-goal',g.id)}</div></section>`).join('')||`<section class="card">${empty('Conserto do carro? Uma viagem? Comece pelo valor e pela data.','goal','Criar plano')}</section>`}</div>${budgetCard()}<div class="notice info">Reservar em envelope não movimenta dinheiro e não é despesa. Transfira entre suas contas em Movimentações. O dinheiro em contas de emergência e investimento já fica protegido e não deve ser reservado novamente em um envelope.</div>`;}
function budgetCard(){const b=F.budgetStatus(state);return `<section class="card"><div class="top"><h2>Seu orçamento para aproveitar</h2>${btn('Ajustar limites','budgets','','link')}</div>${b.rows.length?b.rows.map(r=>`<div class="item"><div><div class="name">${esc(r.category)}</div><p>Limite ${fmt(r.amount)} · Consumido ${fmt(r.spent)}</p></div><div class="amount">${r.remaining<0?'<span class="negative">Excesso '+fmt(-r.remaining)+'</span>':fmt(Math.min(r.remaining,b.free))+' disponível'}</div></div>`).join(''):empty('Escolha limites para lazer e consumo, de acordo com a sua realidade.','budgets','Definir meu orçamento')}<p class="help">Limites mensais são escolhas suas. O disponível de cada categoria também respeita o dinheiro livre total; estes valores não devem ser somados sem conferir o caixa.${b.overallocated?' Os limites restantes ultrapassam o livre em '+fmt(b.overallocated)+'. Ajuste a distribuição.':''}${b.excess?' Você excedeu categorias em '+fmt(b.excess)+'. Reduza limites ainda não usados ou adie desejos; preserve compromissos essenciais.':''}</p></section>`;}
function budgets(){const chosen=new Map((state.settings.budgets||[]).map(b=>[b.category,b.amount]));modal('Orçamento sem culpa',`<form><p class="help">Defina limites mensais para as categorias que quiser acompanhar. Campos vazios não têm limite. Estes valores não são novas despesas e não substituem o cadastro de compromissos. O total disponível continua limitado pelo caixa protegido.</p>${categories.map((c,i)=>field('budget-'+i,c+' (R$)','text',chosen.has(c)?val(chosen.get(c)):'','inputmode="decimal"')).join('')}${formError}<button class="primary">Salvar meus limites</button></form>`);bindForm(v=>commit('Limites mensais de categorias atualizados',s=>s.settings.budgets=categories.map((category,i)=>({category,amount:v['budget-'+i]?F.cents(v['budget-'+i]):null})).filter(x=>x.amount!==null)));}
function wishes(){return heading('Cabe na sua vida. Cabe no seu plano.','Desejar sem culpa, decidir com consciência.',btn('＋ Adicionar desejo','wish','','primary'))+`<div class="notice info">Seu período de reflexão é de ${state.settings.reflection} dia(s). A análise informa o impacto financeiro; a decisão continua sendo sua. Uma data de compra é uma estimativa, condicionada à renda e aos compromissos cadastrados.</div><div class="grid three">${state.wishes.map(w=>{const a=F.assess(state,w.amount,d,w);return `<section class="card"><div class="row between"><span class="item-icon">♡</span><span class="pill ${a.status.includes('não')?'bad':a.status.includes('atenção')?'warn':''}">${esc(w.status)}</span></div><h2 style="margin-top:20px">${esc(w.name)}</h2><div class="report-value">${fmt(w.amount)}</div><p class="help">${esc(w.category)} · prioridade ${w.priority}${w.desired?' · desejado para '+w.desired:''}</p><div class="progress"><span style="width:${w.reserved/w.amount*100}%"></span></div><small>${fmt(w.reserved)} reservados</small><p class="help">${a.status} · ${a.reflection?'Reflexão: '+a.reflection+' dia(s) restantes':'Reflexão concluída'}</p><p class="help">${whenCanBuy(w)}</p>${w.link?`<p><a target="_blank" rel="noopener noreferrer" href="${esc(w.link)}">Ver produto ↗</a></p>`:''}<div class="actions">${btn('Posso comprar?','assess',w.id)}${btn('Reservar','reserve-wish',w.id)}${btn('Editar','wish',w.id)}${w.status!=='comprado'?btn('Registrar compra','buy-wish',w.id):''}</div></section>`;}).join('')||`<section class="card">${empty('A primeira compra planejada começa com um desejo.','wish','Adicionar desejo')}</section>`}</div>`;}
function whenCanBuy(w){if(w.status==='comprado')return 'Compra registrada no histórico.';const s=F.snapshot(state);if(w.amount<=s.free+w.reserved)return 'Cabe no orçamento atual, sujeito às pendências e à reflexão.';let remaining=w.amount-w.reserved;let monthly=Math.max(0,state.settings.salary-F.occurrences(state,d,F.addDays(d,30)).reduce((a,b)=>a+(b.amount||0),0)-s.reserveNow-state.settings.margin);if(!monthly)return 'Sem data segura: complete a renda e o planejamento.';const periods=Math.ceil(Math.max(0,remaining-s.free)/monthly);return `Estimativa otimista: ${periods} salário(s), a partir de ${F.monthDate(s.nextSalary,Math.max(0,periods-1),state.settings.salaryDay)}. Reavalie novas despesas e faturas antes de reservar.`;}
function assets(){const s=F.snapshot(state);return heading('Seu patrimônio, com propósito.','Liquidez para o curto prazo. Consistência para o futuro.',btn('＋ Conta / investimento','account','','primary'))+`<div class="grid three stats">${stat('Patrimônio líquido',s.netWorth,'Ativos − faturas + valores a receber')}${stat('Reserva de emergência',state.accounts.filter(a=>a.kind==='emergency').reduce((v,a)=>v+s.balances[a.id],0),'Saldos declarados, sem retorno presumido')}${stat('Investimentos',state.accounts.filter(a=>a.kind==='investment').reduce((v,a)=>v+s.balances[a.id],0),'Valor registrado nas suas contas')}</div><section class="card"><h2>Contas e distribuição</h2>${s.cardCredit?'<p class="help">Crédito no cartão após estornos: '+fmt(s.cardCredit)+'. Não incluído no saldo bancário ou gasto livre.</p>':''}${state.accounts.map(a=>`<div class="item"><div><div class="name">${esc(a.name)}</div><p>${{cash:'Uso diário · incluída no gasto livre',emergency:'Reserva de emergência · protegida',investment:'Investimento · protegido'}[a.kind]}${a.investmentType?' · '+esc(a.investmentType):''}</p></div><div class="amount">${fmt(s.balances[a.id])}</div></div>`).join('')||empty('Adicione suas contas e saldos atuais.','account','Adicionar conta')}</section><section class="card"><h2>Aportes mensais</h2>${state.entries.filter(e=>e.type==='transfer'&&state.accounts.find(a=>a.id===e.to)?.kind!=='cash').sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="item"><div>${esc(e.name)}<p>${e.date} · ${esc(state.accounts.find(a=>a.id===e.to)?.name)}</p></div><strong>${fmt(e.amount)}</strong></div>`).join('')||empty('Os aportes aparecem quando você transfere para uma conta de reserva ou investimento.')}<p class="help">Para obrigações próximas, priorize liquidez e segurança. Não há cotações ao vivo nem rentabilidade calculada. Atualizações de valor de mercado ainda não estão automatizadas.</p></section>`;}
function reports(){const s=F.snapshot(state);return heading('Entenda para onde o dinheiro foi.','Relatórios pelos seus registros, sem confundir renda com reembolso.')+`<div class="filters"><input type="month" id="report-month" value="${d.slice(0,7)}" aria-label="Mês do relatório"></div><div id="report-body"></div><section class="card"><h2>Evolução do patrimônio</h2><p class="help">Reconstrução dos saldos com os valores iniciais declarados. Compras futuras não entram antes da data. Não representa cotações de mercado.</p><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Ativos em contas</th><th>Patrimônio líquido</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>{const start=F.monthDate(d,-5+i,1),end=F.addDays(F.monthDate(start,1,1),-1),asof=end>d?d:end,h=F.snapshot({...state,purchases:state.purchases.filter(p=>p.date<=asof),entries:state.entries.filter(e=>e.date<=asof)},asof);return `<tr><td>${start.slice(0,7)}</td><td>${state.accounts.some(a=>a.created&&a.created>asof)?'Sem base histórica':fmt(h.assets)}</td><td>${state.accounts.some(a=>a.created&&a.created>asof)?'Sem base histórica':fmt(h.netWorth)}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function reportRows(){if(!$('#report-body'))return;const m=$('#report-month').value,rows=state.entries.filter(e=>!m||e.date.startsWith(m)),p=state.purchases.filter(p=>!m||p.date.startsWith(m)),cats={};for(const e of rows.filter(e=>e.type==='expense'))cats[e.category||'Outros']=(cats[e.category||'Outros']||0)+e.amount;for(const x of p)cats[x.category||'Outros']=(cats[x.category||'Outros']||0)+F.splitRefund(state,x,'Gabriel');const total=Object.values(cats).reduce((a,b)=>a+b,0);$('#report-body').innerHTML=`<div class="grid two"><section class="card"><h2>Consumo pessoal por categoria</h2>${Object.entries(cats).map(([c,v])=>`<div class="item"><span>${esc(c)}</span><strong>${fmt(v)}</strong></div>`).join('')||empty('Sem consumo neste mês.')}<div class="item"><strong>Total</strong><strong>${fmt(total)}</strong></div></section><section class="card"><h2>Natureza das movimentações</h2>${Object.entries(typeNames).map(([t,n])=>`<div class="item"><span>${n}</span><strong>${fmt(rows.filter(e=>e.type===t).reduce((a,e)=>a+e.amount,0))}</strong></div>`).join('')}</section></div><section class="card"><h2>Terceiros por mês da fatura</h2>${Object.entries(F.receivables(state,m)).map(([person,r])=>`<div class="item"><div><strong>${esc(person)}</strong><p>Compras ${fmt(r.total)} · Recebido ${fmt(r.paid)} · Pendente ${fmt(r.pending)}</p></div>${person!=='Não identificado'?btn('Copiar mensagem','collect-month',person):''}</div>`).join('')||empty('Sem compras de terceiros neste mês.')}</section>`;}
function consultant(){return heading('Seu consultor, do seu lado.','Respostas com os seus registros e cálculos que você pode conferir.')+`<section class="chat"><div class="chat-intro"><div class="chat-symbol">✧</div><h2>Vamos pensar no seu próximo passo?</h2><p class="help">Consultor local por regras • sem IA generativa ou custo de API.<br>Não interpreta qualquer assunto: quando faltar informação, consulte o detalhamento financeiro.</p></div><div class="prompts">${['Recebi meu salário. Como distribuir?','Quanto minha mãe ainda me deve?','Posso comprar um perfume de R$ 250 agora?','Por que meu saldo diminuiu?'].map(q=>btn(esc(q),'prompt',q)).join('')}</div><div id="chat-history">${chat.map(c=>`<div class="bubble ${c.role}">${esc(c.text)}</div>`).join('')}</div><form id="chat-form" class="chat-form"><label class="sr-only" for="question">Sua pergunta</label><input id="question" placeholder="Pergunte sobre seu dinheiro…" required maxlength="1000"><button class="primary" aria-label="Enviar pergunta">Enviar ↗</button></form><p class="help">Respostas consideram os registros atuais. Compras não são autorizadas nem bloqueadas pelo consultor.</p></section>`;}
function settings(){return heading('Tudo no seu controle.','Renda, segurança, cópias de backup e transparência.')+`<div class="grid two"><section class="card"><h2>Salário e preferências</h2><p class="help">Salário previsto não entra no saldo até você registrar o recebimento.</p><div class="metric-grid"><div><small>Salário líquido</small><strong>${fmt(state.settings.salary)}</strong></div><div><small>Dia do recebimento</small><strong>${state.settings.salaryDay}</strong></div><div><small>Reflexão para desejos</small><strong>${state.settings.reflection} dias</strong></div><div><small>Margem de segurança escolhida</small><strong>${fmt(state.settings.margin)}</strong></div></div><div class="actions section-space">${btn('Configurar','salary')}${btn('Registrar salário recebido','salary-received')}</div></section><section class="card"><h2>Seus dados são seus.</h2><p class="help">Dados financeiros persistem no IndexedDB deste navegador. Não são enviados a um servidor. Não há login nem sincronização. Quem tem acesso ao seu dispositivo e navegador pode acessar os registros. Limpar os dados do navegador remove os registros.</p><div class="actions">${btn('Exportar backup JSON','backup')}${btn('Importar backup','restore')}${btn('Exportar CSV','export-csv')}</div><p class="help">Backups não são criptografados. Guarde-os em local privado. Para trocar de aparelho, exporte e importe o backup; os bancos locais não se sincronizam automaticamente.</p></section></div><section class="card"><h2>Instalar no iPhone ou computador</h2><p class="help">No Safari do iPhone, abra a URL HTTPS, toque em Compartilhar e “Adicionar à Tela de Início”. No computador, use a opção de instalação do navegador. Depois da primeira abertura, a aplicação e os importadores funcionam offline.</p><div class="install" id="storage-status">Verificando armazenamento…</div><div class="actions section-space">${btn('Pedir armazenamento persistente','persist')}${btn('Patrimônio e contas →','goto','patrimonio')}${btn('Relatórios →','goto','relatorios')}</div></section><section class="card"><h2>Regras aprendidas de classificação</h2><p class="help">Aplicadas pela descrição exata. Sempre revisáveis antes de importar.</p>${state.rules.map(r=>`<div class="item"><div>${esc(r.description)}<p>${esc(r.person)} · ${esc(r.category)}</p></div>${btn('Remover regra','delete-rule',r.id)}</div>`).join('')||empty('Ao corrigir uma compra, você pode salvar a classificação para as próximas importações.')}</section><section class="card"><h2>Histórico auditável</h2><p class="help">Alterações locais registradas na mesma transação dos dados. Reversões mantêm o registro anterior no histórico. Este histórico não é resistente à adulteração por quem controla o dispositivo.</p><div class="table-wrap"><table><thead><tr><th>Quando</th><th>Ação</th></tr></thead><tbody>${state.audit.slice().reverse().slice(0,100).map(a=>`<tr><td>${esc(a.at)}</td><td><details><summary>${esc(a.action.split('\n')[0])}</summary><pre>${esc(a.action+'\n'+JSON.stringify(a.changes||[],null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div></section>`;}
function render(){page=location.hash.slice(1)||'inicio';if(!pages.some(p=>p[0]===page))page='inicio';$('nav').innerHTML=pages.map(([id,icon,label])=>`<a href="#${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}><b aria-hidden="true">${icon}</b>${label}</a>`).join('');$('#breadcrumb').textContent=pages.find(p=>p[0]===page)[2];$('#main').innerHTML=({inicio:dashboard,movimentacoes:movements,cartoes:cards,planejamento:planning,desejos:wishes,patrimonio:assets,relatorios:reports,consultor:consultant,configuracoes:settings}[page])();if(page==='movimentacoes'){movementRows();$$('.filters input,.filters select').forEach(e=>e.oninput=movementRows);}if(page==='cartoes'){purchaseRows();$$('.filters input,.filters select').forEach(e=>e.oninput=purchaseRows);}if(page==='relatorios'){reportRows();$('#report-month').oninput=reportRows;}if(page==='consultor')$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#question').value);};if(page==='configuracoes')navigator.storage?.persisted?.().then(x=>{if($('#storage-status'))$('#storage-status').textContent=x?'Armazenamento persistente concedido pelo navegador. Mantenha backups.':'Armazenamento padrão: o navegador pode remover dados por falta de espaço. Mantenha backups.';});}
function ask(q){if(!q.trim())return;chat.push({role:'user',text:q},{role:'assistant',text:F.consult(state,q)});render();$('#chat-history').lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function account(){modal('Adicionar conta ou investimento',`<form>${field('name','Nome da conta','text','','required maxlength="80"')}${select('kind','Finalidade',option('cash','Conta de uso diário')+option('emergency','Reserva de emergência')+option('investment','Investimento'))}${field('opening','Saldo atual (R$)','text','0,00','required inputmode="decimal"')}${field('investmentType','Tipo de investimento (opcional)','text','','placeholder="Ex.: Tesouro, CDB, fundos" maxlength="80"')}<p class="help">Saldo inicial é o ponto de partida de hoje; não é salário nem receita. Registre apenas contas que pertencem a você.</p>${formError}<button class="primary">Salvar conta</button></form>`);bindForm(v=>commit('Conta cadastrada: '+v.name,s=>s.accounts.push({id:F.uid(),name:v.name.trim(),kind:v.kind,opening:F.cents(v.opening),investmentType:v.investmentType,created:d})));}
function salary(){modal('Configurar minha renda',`<form>${field('salary','Salário líquido mensal (R$)','text',val(state.settings.salary),'required inputmode="decimal"')}${field('salaryDay','Dia do recebimento','number',state.settings.salaryDay,'required min="1" max="31"')}${select('salaryAccount','Conta para receber',accountOptions(state.settings.salaryAccount))}${field('reflection','Dias de reflexão para desejos','number',state.settings.reflection,'required min="0" max="365"')}${field('margin','Margem de segurança adicional (R$)','text',val(state.settings.margin),'required inputmode="decimal"')}<p class="help">Nenhuma divisão percentual é imposta. A margem é uma proteção extra escolhida por você, além das contas e envelopes. Bônus e receitas extraordinárias devem ser lançados separadamente.</p>${formError}<button class="primary">Salvar preferências</button></form>`);bindForm(v=>commit('Preferências de renda atualizadas',s=>Object.assign(s.settings,{salary:F.cents(v.salary),salaryDay:Number(v.salaryDay),salaryAccount:v.salaryAccount,reflection:Number(v.reflection),margin:F.cents(v.margin)})));}
function entry(prefill={}){if(!state.accounts.length){account();return;}modal(prefill.title||'Nova movimentação',`<form>${select('type','Tipo de movimentação',Object.entries(typeNames).filter(([t])=>!['reimbursement','invoice','refund'].includes(t)).map(([t,n])=>option(t,n,prefill.type||'expense')).join(''))}${field('name','Descrição','text',prefill.name||'','required maxlength="120"')}<div class="grid two"><div>${field('amount','Valor (R$)','text',prefill.amount?val(prefill.amount):'','required inputmode="decimal"')}</div><div>${field('date','Data','date',d,'required')}</div></div>${select('account','Conta de origem / recebimento',accountOptions(prefill.account||state.settings.salaryAccount,true))}<div id="transfer-target">${select('to','Conta de destino (transferências)',accountOptions('',true))}</div>${select('category','Categoria',opts(categories,prefill.category||'Outros'))}<p class="help">Dinheiro enviado a terceiros sai do patrimônio e é apresentado separadamente do consumo próprio; este tipo não cria um empréstimo a receber. Receber salário aumenta seu caixa. Transferir entre suas contas preserva o patrimônio. Para pagar faturas ou receber reembolso, use o módulo Cartão compartilhado.</p>${formError}<button class="primary">Registrar movimentação</button></form>`);const toggle=()=>$('#transfer-target').hidden=$('#f-type').value!=='transfer';$('#f-type').onchange=toggle;toggle();bindForm(v=>commit('Movimentação: '+v.name,s=>{if(v.date>d)throw Error('Movimentações realizadas não podem ter data futura. Use Planejamento para contas previstas.');s.entries.push({id:F.uid(),...v,amount:F.cents(v.amount)});}));}
function splitInputs(splits){return `<div id="splits">${splits.map(x=>splitRow(x)).join('')}</div><button type="button" id="add-split" style="margin-top:10px">＋ Outra pessoa</button>`;}
function splitRow(x){return `<div class="split-row"><input aria-label="Responsável" list="persons" class="person" value="${esc(x.person)}" required maxlength="60"><input aria-label="Parte em reais" class="part" inputmode="decimal" value="${val(x.amount)}" required><button type="button" class="remove-split" aria-label="Remover pessoa">×</button></div>`;}
function wireSplits(){$('#add-split').onclick=()=>$('#splits').insertAdjacentHTML('beforeend',splitRow({person:'',amount:0}));$('#splits').onclick=e=>{if(e.target.classList.contains('remove-split')&&$$('.split-row').length>1)e.target.closest('.split-row').remove();};}
function readSplits(){return $$('.split-row').map(row=>({person:$('.person',row).value.trim(),amount:F.cents($('.part',row).value)}));}
function purchaseForm(){modal('Registrar compra no cartão',`<form><datalist id="persons"><option>Gabriel</option><option>Mãe</option><option>Não identificado</option></datalist>${field('description','Descrição da compra','text','','required maxlength="120"')}<div class="grid two"><div>${field('amount','Valor TOTAL da compra (R$)','text','','required inputmode="decimal"')}</div><div>${field('date','Data da compra','date',d,'required')}</div><div>${field('card','Nome do cartão','text','Meu cartão','required maxlength="80"')}</div><div>${field('due','Vencimento da primeira fatura','date',F.addDays(d,15),'required')}</div><div>${field('installments','Número de parcelas','number',1,'required min="1" max="120"')}</div><div>${select('category','Categoria',opts(categories,'Outros'))}</div></div><label>Divisão do valor total (R$)</label>${splitInputs([{person:'Gabriel',amount:0}])}<p class="help">As partes devem somar o total da compra. As parcelas são distribuídas com centavos exatos. Use “Não identificado” quando ainda precisar confirmar a pessoa.</p>${formError}<button class="primary">Registrar compra</button></form>`);wireSplits();bindForm(v=>{let splits=readSplits(),amount=F.cents(v.amount);return commit('Compra no cartão: '+v.description,s=>{const rows=F.purchase(s,{...v,amount,splits});if(rows.some(p=>F.duplicate(s,p)))throw Error('Possível duplicidade: compra igual já cadastrada. Confira o histórico.');s.purchases.push(...rows);});});}
function splitForm(id){const p=state.purchases.find(p=>p.id===id);modal('Responsáveis • '+p.description,`<form><datalist id="persons"><option>Gabriel</option><option>Mãe</option><option>Não identificado</option></datalist><p class="help">Parcela ${p.installment||1}/${p.installments||1} · ${fmt(p.amount)}. Correção desta parcela; para parcelas futuras, revise cada fatura.</p>${select('category','Categoria',opts(categories,p.category))}${splitInputs(p.splits)}<label><input type="checkbox" name="learn"> Aprender descrição exata para novas importações (apenas com um responsável)</label>${formError}<button class="primary">Salvar classificação</button></form>`);wireSplits();bindForm(v=>{let splits=readSplits();return commit('Classificação alterada\nAntes: '+JSON.stringify(p),s=>{const x=s.purchases.find(p=>p.id===id);x.splits=splits;x.category=v.category;if(v.learn){if(splits.length!==1)throw Error('Uma regra automática deve ter um único responsável.');s.rules=s.rules.filter(r=>r.description.toLowerCase()!==p.description.toLowerCase());s.rules.push({id:F.uid(),description:p.description,person:splits[0].person,category:v.category});}});});}
function reimburse(id){if(!state.accounts.length){account();return;}const p=state.purchases.find(p=>p.id===id),shares=F.splitRefund(state,p).filter(x=>!['Gabriel','Não identificado'].includes(x.person));if(!shares.length){toast('Identifique a parte de terceiros nesta compra primeiro.');return;}modal('Registrar reembolso',`<form><p class="help">${esc(p.description)} · fatura ${p.due}. O reembolso aumenta o caixa e reduz o valor a receber. Não é renda.</p>${select('person','Quem reembolsou',shares.map(x=>option(x.person,x.person+' · parte '+fmt(x.amount))).join(''))}${field('amount','Valor recebido (R$)','text','','required inputmode="decimal"')}${field('date','Data de recebimento','date',d,`required max="${d}"`)}${select('account','Conta de recebimento',accountOptions('',true))}${formError}<button class="primary">Registrar recebimento</button></form>`);bindForm(v=>commit('Reembolso: '+v.person+' / '+p.description,s=>{const total=F.splitRefund(s,p,v.person),paid=s.entries.filter(e=>e.type==='reimbursement'&&e.purchase===id&&e.person===v.person).reduce((a,e)=>a+e.amount,0);if(F.cents(v.amount)>total-paid)throw Error('Valor maior que o reembolso pendente.');s.entries.push({id:F.uid(),...v,type:'reimbursement',name:'Reembolso '+v.person+' · '+p.description,purchase:id,amount:F.cents(v.amount)});}));}
function invoicePay(key){if(!state.accounts.length){account();return;}const i=F.invoices(state).find(i=>i.key===key);modal('Pagar fatura • '+i.card,`<form><p class="help">Obrigação integral: ${fmt(i.total)}. Já pago: ${fmt(i.paid)}. Pendente: ${fmt(i.pending)}. O consumo já foi reconhecido nas compras.</p>${field('amount','Valor do pagamento (R$)','text',val(i.pending),'required inputmode="decimal"')}${field('date','Data do pagamento','date',d,`required max="${d}"`)}${select('account','Pagar com a conta',accountOptions('',true))}${formError}<button class="primary">Registrar pagamento</button></form>`);bindForm(v=>commit('Pagamento de fatura: '+key,s=>{let n=F.cents(v.amount);if(n>i.pending)throw Error('Pagamento excede a fatura pendente.');s.entries.push({id:F.uid(),...v,amount:n,name:'Fatura '+i.card,type:'invoice',invoice:key});}));}
function refund(id){if(!state.accounts.length){account();return;}const p=state.purchases.find(p=>p.id===id);modal('Estorno no cartão',`<form><p class="help">${esc(p.description)}: o estorno reduz a compra e as partes proporcionalmente, com centavos exatos. Se já houve reembolso, devolva-o/reverta-o antes de estornar a parte correspondente. Crédito após fatura quitada fica visível no relatório da fatura; não vira saldo bancário.</p>${field('amount','Valor do estorno (R$)','text','','required inputmode="decimal"')}${field('date','Data do estorno','date',d,`required max="${d}"`)}${select('account','Conta de referência (sem movimentação de caixa)',accountOptions('',true))}${formError}<button class="primary">Registrar estorno</button></form>`);bindForm(v=>commit('Estorno: '+p.description,s=>{s.entries.push({id:F.uid(),...v,name:'Estorno '+p.description,type:'refund',purchase:id,amount:F.cents(v.amount)});const rr=F.receivables(s);if(Object.values(rr).some(r=>r.pending<0))throw Error('Há reembolso já recebido superior à nova parte. Reverta o reembolso excedente primeiro.');}));}
function bill(id){const b=state.bills.find(b=>b.id===id)||{name:'',amount:null,due:d,recurring:true,category:'Outros',priority:'1',account:'',estimated:true};modal(id?'Editar compromisso':'Conta fixa ou compromisso',`<form>${field('name','Nome','text',b.name,'required maxlength="120"')}<div class="grid two"><div>${field('amount','Valor previsto (R$) • vazio se não sabe','text',b.amount===null?'':val(b.amount),'inputmode="decimal"')}</div><div>${field('due','Vencimento inicial','date',b.due,'required')}</div></div>${select('category','Categoria',opts(categories,b.category))}${select('priority','Prioridade',option('1','1 · Essencial',b.priority)+option('2','2 · Importante',b.priority)+option('3','3 · Ajustável',b.priority))}${select('account','Conta prevista',`<option value="">Escolher ao pagar</option>`+accountOptions(b.account,true))}<label><input type="checkbox" name="recurring" ${b.recurring?'checked':''}> Repetir mensalmente</label><label><input type="checkbox" name="estimated" ${b.estimated?'checked':''}> Valor ainda é uma estimativa</label><p class="help">Datas nos dias 29–31 se ajustam ao último dia dos meses mais curtos. Pagar encerra somente a ocorrência escolhida.</p>${formError}<button class="primary">Salvar compromisso</button></form>`);bindForm(v=>commit('Compromisso '+(id?'alterado\nAntes: '+JSON.stringify(b):'cadastrado: '+v.name),s=>{let x={...v,id:id||F.uid(),amount:v.amount?F.cents(v.amount):null,recurring:!!v.recurring,estimated:!!v.estimated};if(id)s.bills[s.bills.findIndex(b=>b.id===id)]=x;else s.bills.push(x);}));}
function billPay(key){if(!state.accounts.length){account();return;}const [id,occurrence]=key.split('|'),b=state.bills.find(b=>b.id===id);modal('Pagar • '+b.name,`<form>${field('amount','Valor efetivamente pago (R$)','text',val(b.amount),'required inputmode="decimal"')}${field('date','Data de pagamento','date',d,`required max="${d}"`)}${select('account','Conta',accountOptions(b.account,true))}${formError}<button class="primary">Registrar pagamento</button></form>`);bindForm(v=>commit('Compromisso pago: '+b.name+' / '+occurrence,s=>{if(s.entries.some(e=>e.bill===id&&e.occurrence===occurrence))throw Error('Esta ocorrência já foi paga.');s.entries.push({id:F.uid(),...v,amount:F.cents(v.amount),name:b.name,category:b.category,type:'expense',bill:id,occurrence});}));}
function goal(id){const g=state.goals.find(g=>g.id===id)||{name:'',target:null,reserved:0,due:F.monthDate(d,2),periods:2,priority:'1'};modal(id?'Editar plano futuro':'Planejar uma despesa futura',`<form>${field('name','Nome do plano','text',g.name,'required maxlength="120"')}<div class="grid two"><div>${field('target','Custo estimado (R$) • vazio se não sabe','text',g.target===null?'':val(g.target),'inputmode="decimal"')}</div><div>${field('due','Quando será necessário','date',g.due,'required')}</div></div>${field('periods','Períodos / salários disponíveis para juntar','number',g.periods,'required min="1" max="120"')}${select('priority','Prioridade',option('1','1 · Essencial',g.priority)+option('2','2 · Importante',g.priority)+option('3','3 · Ajustável',g.priority))}<p class="help">O motor divide o valor faltante pelo número exato de períodos informado. R$ 800,00 em dois períodos = R$ 400,00 por período. Reservas existentes são preservadas na edição. Não duplique este mesmo custo em Contas fixas.</p>${formError}<button class="primary">Salvar plano</button></form>`);bindForm(v=>commit('Plano futuro '+(id?'alterado\nAntes: '+JSON.stringify(g):'criado: '+v.name),s=>{let x={...v,id:id||F.uid(),reserved:g.reserved,target:v.target?F.cents(v.target):null,periods:Number(v.periods)};if(id)s.goals[s.goals.findIndex(g=>g.id===id)]=x;else s.goals.push(x);}));}
function wish(id){const w=state.wishes.find(w=>w.id===id)||{name:'',amount:0,reserved:0,category:'Compras',priority:'2',desired:'',link:'',status:'desejado',created:d};modal(id?'Editar desejo':'Um novo desejo',`<form>${field('name','O que você deseja?','text',w.name,'required maxlength="120"')}<div class="grid two"><div>${field('amount','Valor estimado (R$)','text',w.amount?val(w.amount):'','required inputmode="decimal"')}</div><div>${field('desired','Data desejada (opcional)','date',w.desired)}</div></div>${select('category','Categoria',opts(categories,w.category))}${select('priority','Sua prioridade',option('1','1 · Alta',w.priority)+option('2','2 · Média',w.priority)+option('3','3 · Baixa',w.priority))}${field('link','Link do produto (opcional)','url',w.link,'placeholder="https://…"')}${select('status','Status',opts(['desejado','planejado','liberado','adiado',...(w.status==='comprado'?['comprado']:[])],w.status))}<p class="help">Para concluir, use “Registrar compra”. Alterar o status não movimenta dinheiro. A reflexão começa no dia do cadastro.</p>${formError}<button class="primary">Salvar desejo</button></form>`);bindForm(v=>{if(v.link&&!/^https?:\/\//i.test(v.link))throw Error('Use um link http ou https.');return commit('Desejo '+(id?'alterado\nAntes: '+JSON.stringify(w):'criado: '+v.name),s=>{const x={...v,id:id||F.uid(),amount:F.cents(v.amount),reserved:w.reserved,created:w.created};if(id)s.wishes[s.wishes.findIndex(w=>w.id===id)]=x;else s.wishes.push(x);});});}
function reserve(kind,id){const arr=kind==='goal'?'goals':'wishes',g=state[arr].find(g=>g.id===id);if(kind==='wish'&&['comprado','adiado'].includes(g.status)){toast('Reative o desejo antes de reservar.');return;}modal('Envelope • '+g.name,`<form><p class="help">Atualmente reservado: ${fmt(g.reserved)}. Informe o novo total. Isso protege dinheiro que já está nas contas de uso diário; não registra despesa ou transferência.</p>${field('reserved','Novo total reservado (R$)','text',val(g.reserved),'required inputmode="decimal"')}${formError}<button class="primary">Atualizar envelope</button></form>`);bindForm(v=>commit('Envelope atualizado\nAntes: '+JSON.stringify(g),s=>{let n=F.cents(v.reserved),snap=F.snapshot(s),delta=n-g.reserved; // Existing planned contribution can be converted into funded reserve.
if(delta>0&&delta>Math.max(0,snap.cash-snap.envelope-snap.pendingBeforeSalary-s.settings.margin))throw Error('O caixa livre de envelopes e contas antes do salário não cobre essa reserva.');s[arr].find(x=>x.id===id).reserved=n;}));}
function spend(kind,id){if(!state.accounts.length){account();return;}const arr=kind==='goal'?'goals':'wishes',g=state[arr].find(g=>g.id===id);modal('Registrar compra / pagamento • '+g.name,`<form><p class="help">O valor pago sai da conta como despesa pessoal e libera a reserva deste envelope. Este fluxo registra pagamento à vista; para cartão, cadastre a compra em Cartão compartilhado e libere o envelope manualmente.</p>${field('amount','Valor pago (R$)','text',val(kind==='goal'?(g.target??g.reserved):g.amount),'required inputmode="decimal"')}${field('date','Data','date',d,`required max="${d}"`)}${select('account','Conta utilizada',accountOptions('',true))}${select('category','Categoria',opts(categories,g.category||'Transporte'))}${formError}<button class="primary">Confirmar registro</button></form>`);bindForm(v=>commit('Envelope utilizado / pago\nAntes: '+JSON.stringify(g),s=>{s.entries.push({id:F.uid(),...v,type:'expense',name:g.name,amount:F.cents(v.amount),source:id});if(kind==='goal')s.goals=s.goals.filter(g=>g.id!==id);else Object.assign(s.wishes.find(w=>w.id===id),{reserved:0,status:'comprado'});}));}
function explanation(){const s=F.snapshot(state);modal('Como calculamos seu dinheiro livre',`<div class="metric-grid"><div><small>Caixa em contas de uso diário</small><strong>${fmt(s.cash)}</strong></div><div><small>Envelopes já reservados</small><strong>${fmt(s.envelope)}</strong></div><div><small>Contas e faturas antes do salário</small><strong>${fmt(s.pendingBeforeSalary)}</strong></div><div><small>Aporte atual de planos futuros</small><strong>${fmt(s.reserveNow)}</strong></div></div><p class="help">Partimos do caixa, protegemos envelopes e a margem de segurança (${fmt(state.settings.margin)}). Simulamos diariamente os próximos 90 dias, descontando faturas integrais, compromissos pendentes e aportes de planos, incluindo o de hoje. Consideramos salários previstos como estimativas nas datas configuradas. O livre é o menor saldo dessa simulação, limitado a zero. Reservas e investimentos em contas separadas não entram nesse caixa.</p><p><strong>Livre para aproveitar: ${fmt(s.free)}</strong></p><p class="help">Reembolsos pendentes não financiam compras. Gastos não cadastrados, valores desconhecidos e mudanças na renda afetam a confiabilidade. O modelo não garante solvência além de 90 dias.</p><details><summary>Eventos usados na simulação</summary>${s.events.map(e=>`<p>${e.date} · ${esc(e.name)} · ${fmt(e.amount)} · ${e.confirmed?'Confirmado':'Estimativa'}</p>`).join('')||'<p>Nenhum evento.</p>'}</details>`);}
function assessWish(id){const w=state.wishes.find(w=>w.id===id),a=F.assess(state,w.amount,d,w);modal(a.status,`<h3>${esc(w.name)} · ${fmt(w.amount)}</h3><p style="white-space:pre-wrap;font-size:13px;line-height:1.9">${esc(a.explanation)}</p><p class="help">${whenCanBuy(w)}</p>`);}
function confirmAction(title,desc,fn){modal(title,`<p class="help">${esc(desc)}</p><form>${formError}<button class="primary">Confirmar</button> <button type="button" id="cancel-confirm">Cancelar</button></form>`);$('#cancel-confirm').onclick=close;bindForm(fn);}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function backup(){download(JSON.stringify(state,null,2),'clareza-backup-'+d+'.json');}
function restore(){modal('Restaurar backup local',`<p class="help">A restauração substitui seus registros neste navegador. Exporte o backup atual primeiro. Só importe arquivos seus e confiáveis.</p><input id="backup-file" type="file" accept=".json"><p id="form-error" class="error"></p><div id="restore-preview"></div>`);$('#backup-file').onchange=async e=>{try{const file=e.target.files[0];if(file.size>20e6)throw Error('Backup acima de 20 MB.');const data=F.validate(JSON.parse(await file.text()));$('#restore-preview').innerHTML=`<p>${data.accounts.length} conta(s), ${data.entries.length} movimentação(ões), ${data.purchases.length} compra(s).</p><button id="restore-go" class="primary">Substituir pelos dados deste backup</button>`;$('#restore-go').onclick=()=>commit('Backup restaurado (substituição explícita)',s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,data);});}catch(e){$('#form-error').textContent=e.message;}};}
async function copyCollection(person,month=''){const r=F.receivables(state,month)[person];if(!r)return;const msg=`Oi, ${person}! Tudo bem? Conferi ${month?'a fatura de '+month:'as compras no meu cartão'}: sua parte ficou em ${fmt(r.total)} e já recebi ${fmt(r.paid)}. Ainda faltam ${fmt(r.pending)}. Quando puder, consegue me transferir? Obrigado!`;try{await navigator.clipboard.writeText(msg);toast('Mensagem copiada.');}catch{modal('Mensagem para copiar',`<textarea readonly aria-label="Mensagem de cobrança">${esc(msg)}</textarea>`);}}
function exportCSV(){const quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"',safe=s=>/^[=+\-@]/.test(String(s))?"'"+s:s;download('\uFEFF'+[['data','descricao','tipo','valor_centavos','conta','categoria'],...state.entries.map(e=>[e.date,safe(e.name),e.type,e.amount,safe(state.accounts.find(a=>a.id===e.account)?.name),safe(e.category)])].map(r=>r.map(quote).join(';')).join('\r\n'),'clareza-movimentacoes-'+d+'.csv','text/csv;charset=utf-8');}
async function action(name,id){switch(name){case'goto':location.hash=id;break;case'account':account();break;case'salary':salary();break;case'budgets':budgets();break;case'entry':entry();break;case'salary-received':entry({title:'Registrar salário recebido',type:'income',name:'Salário',amount:state.settings.salary});break;case'purchase':purchaseForm();break;case'split':splitForm(id);break;case'reimburse':reimburse(id);break;case'pay-invoice':invoicePay(id);break;case'refund':refund(id);break;case'bill':bill(id);break;case'pay-bill':billPay(id);break;case'goal':goal(id);break;case'wish':wish(id);break;case'reserve-goal':reserve('goal',id);break;case'reserve-wish':reserve('wish',id);break;case'spend-goal':spend('goal',id);break;case'buy-wish':spend('wish',id);break;case'assess':assessWish(id);break;case'explain':explanation();break;case'prompt':ask(id);break;case'backup':backup();break;case'restore':restore();break;case'export-csv':exportCSV();break;case'collect':await copyCollection(id);break;case'collect-month':await copyCollection(id,$('#report-month').value);break;case'persist':toast(await navigator.storage?.persist?.()?'Armazenamento persistente concedido.':'O navegador não concedeu persistência. Mantenha backups.');break;case'import':await importForm();break;case'delete-entry':{const old=state.entries.find(e=>e.id===id);confirmAction('Reverter movimentação?','A operação será removida dos saldos. O registro original será preservado no histórico de alterações.',()=>commit('Movimentação revertida\nRegistro anterior: '+JSON.stringify(old),s=>s.entries=s.entries.filter(e=>e.id!==id)));break;}case'delete-bill':case'delete-goal':case'delete-rule':{const arr=name==='delete-bill'?'bills':name==='delete-goal'?'goals':'rules',old=state[arr].find(x=>x.id===id);confirmAction('Encerrar este registro?','Os lançamentos já realizados serão mantidos. Reservas de envelopes encerrados serão liberadas.',()=>commit('Registro encerrado\nAnterior: '+JSON.stringify(old),s=>s[arr]=s[arr].filter(x=>x.id!==id)));break;}}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)action(a.dataset.action,a.dataset.id).catch(e=>toast(e.message));});$('#quick').onclick=()=>entry();$('#close').onclick=close;window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
let importModule;
async function importForm(){if(!importModule)importModule=await import('./importer.js');await importModule.show({state,getState:()=>state,modal,esc,fmt,field,select,option,opts,categories,commit,toast});}
try{state=await open();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Modo offline indisponível neste navegador.'));}catch(e){$('#main').innerHTML=`<div class="notice"><h2>Não foi possível abrir os dados locais.</h2><p>${esc(e.message)}</p><p>Use um navegador com IndexedDB habilitado. Seus registros não serão substituídos.</p></div>`;}
